select case when budget >= 3816000 then 'LARGE' else 'SMALL' end as budget_tier, count_if(location = 'Chiang Mai') as chiang_mai_events, count(distinct dept_name) as distinct_dept_names, sum(budget) filter (where location = 'Singapore') as singapore_total_budget, size(collect_set(dept_name)) as num_dept_names, stddev_samp(budget) as budget_stddev from departments group by rollup (case when budget >= 3816000 then 'LARGE' else 'SMALL' end) order by singapore_total_budget desc
